mapper.select:
SELECT regexp_replace(request_uri, '/[0-9]+', '/{id}', 'g') AS uriPattern,
       COUNT(*)                                             AS requestCount,
       COUNT(DISTINCT remote_addr)                          AS visitorCount,
       COALESCE(ROUND(AVG(process_time)), 0)::bigint        AS avgProcessTime
  FROM tb_system_log
 WHERE created_at >= #{from}
   AND created_at <  #{to}
 GROUP BY 1
 ORDER BY requestCount DESC, uriPattern
 LIMIT #{limit}
